/**
 * CE-02.2 (#47) decision D2: manifest schema version 2 stays. A v2 reader
 * accepts both a CE-02.1 manifest (with legacy `range` entries) and a
 * CE-02.2 one (finite values only).
 *
 *   - the reader is `validateArtifactSet`, byte-identical to its CE-02.1
 *     source (pinned SHA-256 of 8d8f3b7);
 *   - fixtures/ce022-manifest-v2/ce021-artifact-set.json is an artifact set
 *     generated by the CE-02.1 compiler (8d8f3b7) with generate.cjs; the
 *     CE-02.2 set is generated here from the same definition;
 *   - for a manifest reader, `properties.catalogVersion` and `digest` mark
 *     the change (`properties.schemaVersion` is a snapshot field, not
 *     projected into the manifest).
 */

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const { loadCompiler } = require('./session-helpers');

const compiler = loadCompiler();
const REPO = path.resolve(__dirname, '../../../..');
const FIXTURE = path.join(__dirname, 'fixtures/ce022-manifest-v2');
const CE021_COMMIT = '8d8f3b7847f70602d866d98234c73c4fc5b07402';
// sha256 of packages/compiler/src/artifacts/metadata/artifact-set.js at
// CE021_COMMIT (`git show <commit>:<path> | sha256sum`).
const CE021_READER_SHA256 =
  'd1d6b03e498bdebaa049a34038d7aff4df58fbc3f7e02a189b635222711b79b1';

const ce021 = JSON.parse(
  fs.readFileSync(path.join(FIXTURE, 'ce021-artifact-set.json'), 'utf8'),
);
const definition = require('./fixtures/ce022-manifest-v2/definition.cjs');

function ce022Set() {
  const ds = compiler.buildDesignSystem(definition);
  return compiler.createArtifactSet(ds.snapshot, {
    designModuleFile: 'design.pandamstyle.js',
    declarationsFile: 'design.pandamstyle.d.ts',
    designModule: compiler.generateDesignSystemModule({ designSystem: ds }),
    declarations: compiler.generateDesignSystemDeclarations(ds.snapshot),
    manifest: `${JSON.stringify(ds.snapshot.tooling.manifest, null, 2)}\n`,
    css: compiler.withDesignSystemCssIdentity(
      ds.renderCss(),
      ds.snapshot.identity,
    ),
  });
}

describe('the manifest v2 reader', () => {
  test('is the CE-02.1 reader, unchanged', () => {
    const bytes = fs.readFileSync(
      path.join(
        REPO,
        'packages/compiler/src/artifacts/metadata/artifact-set.js',
      ),
    );
    expect(crypto.createHash('sha256').update(bytes).digest('hex')).toBe(
      CE021_READER_SHA256,
    );
    expect(ce021.provenance.sourceCommit).toBe(CE021_COMMIT);
  });

  test('accepts the CE-02.1 artifact set (legacy ranges)', () => {
    const manifest = JSON.parse(ce021.contents.manifest);
    expect(manifest.manifestSchemaVersion).toBe(2);
    expect(manifest.properties.catalogVersion).toBe(1);
    expect(manifest.properties.byProperty.opacity).toEqual({
      range: { min: 0, max: 1, legacy: true },
    });
    expect(compiler.validateArtifactSet(ce021.metadata, ce021.contents)).toBe(
      true,
    );
  });

  test('accepts the CE-02.2 artifact set (finite values)', () => {
    const set = ce022Set();
    const manifest = JSON.parse(set.contents.manifest);
    expect(manifest.manifestSchemaVersion).toBe(2);
    expect(set.metadata.manifestSchemaVersion).toBe(2);
    expect(set.contents.manifest).not.toMatch(/"range"/);
    expect(manifest.properties.byProperty.opacity.values).toHaveLength(21);
    expect(compiler.validateArtifactSet(set.metadata, set.contents)).toBe(true);
  });

  test('catalogVersion and digest mark the change for a manifest reader', () => {
    const before = JSON.parse(ce021.contents.manifest).properties;
    const after = JSON.parse(ce022Set().contents.manifest).properties;
    expect([before.catalogVersion, after.catalogVersion]).toEqual([1, 2]);
    expect(after.digest).not.toBe(before.digest);
    // The snapshot field is not projected into the manifest.
    expect(after).not.toHaveProperty('schemaVersion');
    expect(before).not.toHaveProperty('schemaVersion');
  });

  test('the identity of the system is unchanged across the two compilers', () => {
    const set = ce022Set();
    for (const field of [
      'systemId',
      'registryDigest',
      'abiVersion',
      'compilerContractVersion',
      'manifestSchemaVersion',
    ]) {
      expect({ field, value: set.metadata[field] }).toEqual({
        field,
        value: ce021.metadata[field],
      });
    }
  });

  test('a tampered CE-02.1 set is still refused', () => {
    const contents = {
      ...ce021.contents,
      manifest: ce021.contents.manifest.replace(
        '"legacy": true',
        '"legacy": false',
      ),
    };
    expect(contents.manifest).not.toBe(ce021.contents.manifest);
    expect(() =>
      compiler.validateArtifactSet(ce021.metadata, contents),
    ).toThrow(/manifest/);
  });
});
